parameters.functionCode:
const items = $input.all();

// Categorize conversations by quality
const positiveExamples = [];
const negativeExamples = [];
const neutralExamples = [];

items.forEach(item => {
  const feedback = item.json.user_feedback;
  const example = {
    prompt: item.json.user_message,
    completion: item.json.bot_response,
    metadata: {
      conversation_id: item.json.conversation_id,
      feedback: feedback,
      sentiment: item.json.sentiment,
      resolved: item.json.resolved,
      timestamp: item.json.created_at
    }
  };

  if (feedback >= 4 || (feedback >= 3 && item.json.resolved)) {
    positiveExamples.push(example);
  } else if (feedback <= 2) {
    negativeExamples.push(example);
  } else {
    neutralExamples.push(example);
  }
});

// Create training metrics
const trainingMetrics = {
  total_examples: items.length,
  positive_examples: positiveExamples.length,
  negative_examples: negativeExamples.length,
  neutral_examples: neutralExamples.length,
  quality_score: positiveExamples.length / items.length,
  avg_feedback: items.reduce((sum, item) => sum + (item.json.user_feedback || 0), 0) / items.length,
  resolution_rate: items.filter(item => item.json.resolved).length / items.length
};

// Extract common patterns from negative examples
const negativePatterns = {};
negativeExamples.forEach(ex => {
  const keywords = ex.prompt.toLowerCase().split(/\s+/);
  keywords.forEach(word => {
    if (word.length > 4) {
      negativePatterns[word] = (negativePatterns[word] || 0) + 1;
    }
  });
});

const topNegativePatterns = Object.entries(negativePatterns)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 20)
  .map(([word, count]) => ({ keyword: word, occurrences: count }));

return {
  json: {
    training_id: `training_${Date.now()}`,
    timestamp: new Date().toISOString(),
    training_metrics: trainingMetrics,
    positive_examples: positiveExamples.slice(0, 500),
    negative_examples: negativeExamples,
    problematic_patterns: topNegativePatterns,
    recommendation: trainingMetrics.quality_score >= 0.7 ? 
      'Training data quality is good. Proceed with fine-tuning.' : 
      'Warning: Low quality training data. Review and clean data before training.'
  }
};

