// Generate improved training examples based on negative feedback
const trainingData = $input.item.json;
const negativeExamples = trainingData.negative_examples || [];

// Format for OpenAI fine-tuning JSONL
const finetuningExamples = trainingData.positive_examples.map(ex => ({
  messages: [
    { role: 'system', content: 'You are a helpful, accurate, and friendly customer support assistant.' },
    { role: 'user', content: ex.prompt },
    { role: 'assistant', content: ex.completion }
  ]
}));

// Generate synthetic improved examples for negative cases
const syntheticExamples = negativeExamples.slice(0, 50).map(ex => ({
  original_prompt: ex.prompt,
  original_response: ex.completion,
  feedback: ex.metadata.feedback,
  needs_improvement: true
}));

return {
  json: {
    ...trainingData,
    finetuning_data: {
      format: 'openai_jsonl',
      total_examples: finetuningExamples.length,
      examples: finetuningExamples,
      estimated_cost: (finetuningExamples.length * 0.008).toFixed(2),
      estimated_training_time: Math.ceil(finetuningExamples.length / 100) + ' hours'
    },
    examples_needing_improvement: syntheticExamples
  }
};

const items = $input.all();
const trainingData = items.find(item => item.json.training_id)?.json;
const gptAnalysis = items.find(item => item.json.choices);
const finetuningJob = items.find(item => item.json.id && item.json.status);

const analysis = gptAnalysis ? JSON.parse(gptAnalysis.json.choices[0].message.content) : {};

// Generate training report
const result = {
  training_id: trainingData?.training_id,
  timestamp: trainingData?.timestamp,
  training_summary: {
    data_quality_score: (trainingData?.training_metrics.quality_score * 100).toFixed(1) + '%',
    total_examples: trainingData?.training_metrics.total_examples,
    positive_examples: trainingData?.training_metrics.positive_examples,
    negative_examples: trainingData?.training_metrics.negative_examples,
    avg_user_feedback: trainingData?.training_metrics.avg_feedback.toFixed(2),
    resolution_rate: (trainingData?.training_metrics.resolution_rate * 100).toFixed(1) + '%'
  },
  ai_analysis: {
    improvement_suggestions: analysis.improvement_suggestions || [],
    failure_patterns: analysis.failure_patterns || [],
    focus_areas: analysis.focus_areas || [],
    response_templates: analysis.response_templates || [],
    quality_strategies: analysis.quality_strategies || []
  },
  problematic_patterns: trainingData?.problematic_patterns || [],
  fine_tuning: {
    status: finetuningJob ? 'initiated' : 'pending_manual_review',
    job_id: finetuningJob?.json.id || null,
    model: finetuningJob?.json.model || 'gpt-3.5-turbo',
    training_file_id: finetuningJob?.json.training_file || null,
    estimated_cost: trainingData?.finetuning_data.estimated_cost,
    estimated_time: trainingData?.finetuning_data.estimated_training_time
  },
  recommendations: [
    trainingData?.recommendation,
    `Focus on improving ${trainingData?.negative_examples.length} low-rated interactions`,
    `Address common failure patterns in: ${trainingData?.problematic_patterns.slice(0, 5).map(p => p.keyword).join(', ')}`,
    ...(analysis.key_recommendations || [])
  ],
  metadata: {
    training_providers: ['openai_gpt4_analysis', 'openai_finetuning'],
    processing_time_ms: Date.now() - new Date(trainingData?.timestamp).getTime()
  }
};

return { json: result };

